@if($appointments->count())<div class="table-responsive"><table class="table mb-0"><thead><tr><th>Appointment</th><th>Doctor / patient</th><th>Service</th><th>Status</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody>@foreach($appointments as $a)<tr><td><strong>{{ $a->starts_at->timezone(config('clinic.timezone'))->format('d M Y') }}</strong><div class="small text-muted">{{ $a->starts_at->timezone(config('clinic.timezone'))->format('H:i') }} · 30 minutes</div></td><td>{{ $a->doctor->user->name }}@if(auth()->user()->role!=='patient')<div class="small text-muted">{{ $a->patient->name }}</div>@endif</td><td>{{ $a->service->name }}</td><td><span class="badge status-{{ $a->status }}">{{ ucfirst(str_replace('_',' ',$a->status)) }}</span></td><td><a class="btn btn-sm btn-outline-success" href="{{ route('appointments.show',$a) }}">Details ↗</a></td></tr>@endforeach</tbody></table></div>@else<div class="empty-state"><h3 class="h5">No appointments here yet.</h3><p class="text-muted mb-0">Appointments will appear here when they match this view.</p>@if(auth()->user()->role==='patient')<a class="btn btn-primary mt-3" href="{{ route('appointments.create') }}">Find your next appointment</a>@endif</div>@endif
